<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;use App\Models\{Leave,TimeClock,User};use Illuminate\Http\Request;use Illuminate\Support\Carbon;
class ReportController extends Controller {
 public function analytics(Request $r){abort_unless($r->user()->hasPermission('attendance.view'),403);$start=now()->startOfMonth();$daily=TimeClock::whereBetween('clock_in',[$start,now()])->selectRaw('DATE(clock_in) day, COUNT(*) total, SUM(CASE WHEN status="late" THEN 1 ELSE 0 END) late')->groupBy('day')->orderBy('day')->get();$absent=$this->missingUsers(today());return view('admin.analytics',compact('daily','absent'));}
 public function missing(Request $r){abort_unless($r->user()->hasPermission('attendance.view'),403);$date=Carbon::parse($r->date??today());$users=$this->missingUsers($date);return view('admin.missing',compact('users','date'));}
 public function leaveSummary(Request $r){abort_unless($r->user()->hasPermission('attendance.view'),403);$users=User::where('employeed',true)->withCount(['leaves as medical_used'=>fn($q)=>$q->where(['leave_type'=>'medical','status'=>'approved']),'leaves as casual_used'=>fn($q)=>$q->where(['leave_type'=>'casual','status'=>'approved']),'leaves as half_days'=>fn($q)=>$q->where(['leave_type'=>'half_day','status'=>'approved'])])->paginate(25);return view('admin.leave-summary',compact('users'));}
 public function export(Request $r,string $range){abort_unless($r->user()->hasPermission('reports.export'),403);[$start,$end]=$this->period($range,$r);$rows=TimeClock::with('user')->whereBetween('clock_in',[$start,$end])->get();return response()->streamDownload(function()use($rows){$out=fopen('php://output','w');fputcsv($out,['Employee','Email','Department','Date','Clock In','Clock Out','Worked Seconds','Status']);foreach($rows as $x)fputcsv($out,[$x->user->name,$x->user->email,$x->user->department,$x->clock_in?->toDateString(),$x->clock_in?->format('H:i'),$x->clock_out?->format('H:i'),$x->total_duration,$x->status]);fclose($out);},"attendance-$range.csv",['Content-Type'=>'text/csv']);}
 public function lateAbsent(Request $r){abort_unless($r->user()->hasPermission('reports.export'),403);$date=Carbon::parse($r->date??today());$late=TimeClock::with('user')->whereDate('clock_in',$date)->where('status','late')->get();$absent=$this->missingUsers($date);return response()->streamDownload(function()use($late,$absent,$date){$o=fopen('php://output','w');fputcsv($o,['Type','Employee','Department','Date']);foreach($late as $x)fputcsv($o,['Late',$x->user->name,$x->user->department,$date->toDateString()]);foreach($absent as $u)fputcsv($o,['Absent',$u->name,$u->department,$date->toDateString()]);fclose($o);},'late-absent-'.$date->toDateString().'.csv');}
 private function period(string $range,Request $r):array{$now=now();return match($range){'today'=>[$now->copy()->startOfDay(),$now->copy()->endOfDay()],'week'=>[$now->copy()->startOfWeek(),$now->copy()->endOfWeek()],'month'=>[$now->copy()->startOfMonth(),$now->copy()->endOfMonth()],'quarter'=>[$now->copy()->firstOfQuarter(),$now->copy()->lastOfQuarter()],'half-year'=>[$now->month<=6?$now->copy()->startOfYear():$now->copy()->month(7)->startOfMonth(),$now->month<=6?$now->copy()->month(6)->endOfMonth():$now->copy()->endOfYear()],'filters'=>[Carbon::parse($r->start_date??today())->startOfDay(),Carbon::parse($r->end_date??today())->endOfDay()],default=>abort(404)};}
 private function missingUsers(Carbon $date){return User::where('employeed',true)->whereNotIn('role',['super_admin','admin','manage_admin','qa_admin'])->whereDoesntHave('timeClocks',fn($q)=>$q->whereDate('clock_in',$date))->get();}
}
